using System;
using System.Collections.Generic;
using System.IO;
using System.IO.Compression;
using System.Linq;
using System.Runtime.InteropServices;
using System.Security.Cryptography;
using System.Text;
using System.Threading;
using System.Windows.Forms;
using Newtonsoft.Json.Linq;
using OfficeX.Core;
namespace OfficeX.ExcelHost {
 // The model receives opaque checkpoint IDs. Keys and checkpoint bytes never cross the UI bridge.
 sealed class OfficeFiles:IDisposable {
  readonly dynamic application;readonly string app;readonly Func<OfficeAutomationPort> binding;
  readonly string folder;readonly Dictionary<string,Checkpoint> checkpoints=new Dictionary<string,Checkpoint>();
  sealed class Checkpoint {public string Id,Label,Name,Extension,Hash,Path,State,Validation;public DateTime At;}
  public string Folder=>folder;
  public OfficeFiles(object application,string app,Func<OfficeAutomationPort> binding){this.application=application;this.app=app;this.binding=binding;folder=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"OfficeX","Work",Guid.NewGuid().ToString("N"));Directory.CreateDirectory(folder);}
  OfficeFiles(object application,string app,Func<OfficeAutomationPort> binding,string folder,Dictionary<string,Checkpoint> checkpoints){this.application=application;this.app=app;this.binding=binding;this.folder=folder;this.checkpoints=checkpoints;}
  public OfficeFiles Fork(Func<OfficeAutomationPort> binding)=>new OfficeFiles(application,app,binding,folder,checkpoints);
  static void Release(object o){if(o!=null&&Marshal.IsComObject(o))Marshal.ReleaseComObject(o);}
  static string Hash(byte[] data){using(var sha=SHA256.Create())return BitConverter.ToString(sha.ComputeHash(data)).Replace("-","").ToLowerInvariant();}
  public string CheckedPath(string path,params string[] extensions){var p=Path.GetFullPath(path??"");if(!String.Equals(Path.GetDirectoryName(p),folder,StringComparison.OrdinalIgnoreCase)||!File.Exists(p)||extensions.Length>0&&!extensions.Contains(Path.GetExtension(p),StringComparer.OrdinalIgnoreCase))throw new OfficeFault("artifact_unavailable");if((File.GetAttributes(folder)&FileAttributes.ReparsePoint)!=0||(File.GetAttributes(p)&FileAttributes.ReparsePoint)!=0)throw new OfficeFault("artifact_unavailable");return p;}
  string FreshPath(string extension)=>Path.Combine(folder,Guid.NewGuid().ToString("N")+extension);
  string ValidateDocument(object value){dynamic doc=value;var observations=new List<object>();object collection=null;try{
   if(app=="word"){object content=null,tables=null,sections=null,images=null;try{content=doc.Content;tables=doc.Tables;sections=doc.Sections;images=doc.InlineShapes;observations.Add(new{text=(string)((dynamic)content).Text,tables=(int)((dynamic)tables).Count,sections=(int)((dynamic)sections).Count,images=(int)((dynamic)images).Count});}finally{Release(images);Release(sections);Release(tables);Release(content);}}
   else if(app=="powerpoint"){collection=doc.Slides;for(int i=1;i<=(int)((dynamic)collection).Count;i++){object slide=null,shapes=null;try{slide=((dynamic)collection).Item(i);shapes=((dynamic)slide).Shapes;var contents=new List<object>();for(int j=1;j<=(int)((dynamic)shapes).Count;j++){object shape=null,frame=null,text=null;try{shape=((dynamic)shapes).Item(j);string words="";if(Convert.ToInt32(((dynamic)shape).HasTextFrame)!=0){frame=((dynamic)shape).TextFrame;text=((dynamic)frame).TextRange;words=(string)((dynamic)text).Text;}contents.Add(new{type=(int)((dynamic)shape).Type,text=words,left=(float)((dynamic)shape).Left,top=(float)((dynamic)shape).Top,width=(float)((dynamic)shape).Width,height=(float)((dynamic)shape).Height});}finally{Release(text);Release(frame);Release(shape);}}observations.Add(contents);}finally{Release(shapes);Release(slide);}}}
   else{collection=doc.Worksheets;for(int i=1;i<=(int)((dynamic)collection).Count;i++){object sheet=null,range=null;try{sheet=((dynamic)collection).Item(i);range=((dynamic)sheet).UsedRange;double count=Convert.ToDouble(((dynamic)range).CountLarge);observations.Add(new{name=(string)((dynamic)sheet).Name,address=(string)((dynamic)range).Address,formula=count<=20000?((dynamic)range).Formula:null,largeRange=count>20000});}finally{Release(range);Release(sheet);}}}
   return Wire.Hash(observations);
  }finally{Release(collection);}}
  public string State(){binding().CheckSource();dynamic doc=binding().BoundDocument;if(app=="word")return Hash(Encoding.UTF8.GetBytes((string)doc.WordOpenXML));var path=Copy();try{using(var zip=ZipFile.OpenRead(path)){var bytes=new MemoryStream();foreach(var e in zip.Entries.OrderBy(x=>x.FullName,StringComparer.Ordinal)){if(e.FullName=="docProps/core.xml"||e.FullName.StartsWith("docProps/thumbnail"))continue;var name=Encoding.UTF8.GetBytes(e.FullName);bytes.Write(name,0,name.Length);using(var source=e.Open())source.CopyTo(bytes);}return Hash(bytes.ToArray());}}finally{File.Delete(path);}}
  string Copy(){binding().CheckSource();dynamic doc=binding().BoundDocument;bool macros=false;try{macros=(bool)doc.HasVBProject;}catch{}string extension=app=="word"?".xml":app=="powerpoint"?(macros?".pptm":".pptx"):Path.GetExtension((string)doc.Name);if(app=="excel"&&String.IsNullOrEmpty(extension))extension=macros?".xlsm":".xlsx";var path=FreshPath(extension);
   if(app=="word")File.WriteAllText(path,(string)doc.WordOpenXML,new UTF8Encoding(false));else if(app=="powerpoint")doc.SaveCopyAs(path,macros?25:24);else doc.SaveCopyAs(path);
   if(!File.Exists(path)||new FileInfo(path).Length==0)throw new OfficeFault("checkpoint_failed");return path;
  }
  public object CheckpointNow(string label){var path=Copy();try{var data=File.ReadAllBytes(path);var c=new Checkpoint{Id=Guid.NewGuid().ToString("N"),Label=(label??"문서 변경 전").Substring(0,Math.Min(200,(label??"문서 변경 전").Length)),Name=binding().DocumentName,Extension=Path.GetExtension(path),Hash=Hash(data),State=State(),Validation=ValidateDocument(binding().BoundDocument),At=DateTime.UtcNow};c.Path=FreshPath(".checkpoint");File.WriteAllBytes(c.Path,ProtectedData.Protect(data,null,DataProtectionScope.CurrentUser));checkpoints.Add(c.Id,c);return new{id=c.Id,label=c.Label,document=c.Name,createdAt=c.At.ToString("o"),encrypted=true};}finally{File.Delete(path);}}
  public object ListCheckpoints()=>checkpoints.Values.OrderByDescending(x=>x.At).Select(c=>new{id=c.Id,label=c.Label,document=c.Name,createdAt=c.At.ToString("o"),restoresAs="new_document"}).ToArray();
  public object ExportCopy(){var state=State();var path=Copy();return new{status="verified",path,format=Path.GetExtension(path).TrimStart('.'),sourceState=state,document=binding().DocumentName};}
  public object ExportPdf(CancellationToken token){binding().CheckSource();token.ThrowIfCancellationRequested();var path=FreshPath(".pdf");dynamic doc=binding().BoundDocument;if(app=="word")doc.ExportAsFixedFormat(path,17);else if(app=="powerpoint")doc.ExportAsFixedFormat(path,2);else doc.ExportAsFixedFormat(0,path);CheckedPath(path,".pdf");return new{status="verified",path,bytes=new FileInfo(path).Length};}
  public object SelectInput(){using(var d=new OpenFileDialog{Title="가져올 파일",Filter="문서|*.pdf;*.docx;*.docm;*.pptx;*.pptm;*.xlsx;*.xlsm;*.md;*.markdown;*.html;*.htm;*.txt;*.csv",Multiselect=false}){if(d.ShowDialog()!=DialogResult.OK)return new{status="rejected"};var path=FreshPath(Path.GetExtension(d.FileName));File.Copy(d.FileName,path);return new{status="verified",path,name=Path.GetFileName(d.FileName)};}}
  public object SaveArtifact(string path,string title){path=CheckedPath(path);using(var d=new SaveFileDialog{Title="파일 저장",FileName=Path.GetFileName(title??path),DefaultExt=Path.GetExtension(path).TrimStart('.'),AddExtension=true,OverwritePrompt=true}){if(d.ShowDialog()!=DialogResult.OK)return new{kind="save_artifact",status="rejected",saved=false};File.Copy(path,d.FileName,true);bool match=Hash(File.ReadAllBytes(d.FileName))==Hash(File.ReadAllBytes(path));return new{kind="save_artifact",status=match?"verified":"partial",saved=match,document=Path.GetFileName(d.FileName)};}}
  // Restores the complete checkpoint as a visible copy. The document with later edits remains open.
  public object Restore(string id,CancellationToken token){if(id==null||!checkpoints.TryGetValue(id,out var c))throw new OfficeFault("checkpoint_unavailable");token.ThrowIfCancellationRequested();var data=ProtectedData.Unprotect(File.ReadAllBytes(c.Path),null,DataProtectionScope.CurrentUser);if(Hash(data)!=c.Hash)throw new OfficeFault("checkpoint_corrupt");var path=FreshPath(c.Extension);File.WriteAllBytes(path,data);OpenCopy(path);object restored=app=="word"?application.ActiveDocument:app=="powerpoint"?application.ActivePresentation:application.ActiveWorkbook;bool matches;try{matches=ValidateDocument(restored)==c.Validation;}finally{Release(restored);}return new{kind="rollback_document",status=matches?"verified":"partial",mutated=true,saved=false,checkpointId=id,document=ActiveName(),restoredAs="new_document",originalRetained=true};}
  string ActiveName(){object doc=null;try{doc=app=="word"?application.ActiveDocument:app=="powerpoint"?application.ActivePresentation:application.ActiveWorkbook;return (string)((dynamic)doc).Name;}finally{Release(doc);}}
  public void OpenCopy(string path){path=CheckedPath(path,app=="word"?".docx":app=="powerpoint"?".pptx":".xlsx",app=="word"?".xml":app=="powerpoint"?".pptm":".xlsm",app=="excel"?".xlsb":".docm",app=="excel"?".xls":".rtf",app=="word"?".html":".csv");object collection=null,doc=null;int security=0;bool changed=false;
   try{security=Convert.ToInt32(application.AutomationSecurity);application.AutomationSecurity=3;changed=true;collection=app=="word"?application.Documents:app=="powerpoint"?application.Presentations:application.Workbooks;
    if(app=="word")doc=((dynamic)collection).Open(FileName:path,ConfirmConversions:false,ReadOnly:false,AddToRecentFiles:false,Visible:true);
    else if(app=="powerpoint")doc=((dynamic)collection).Open(path,0,-1,-1);
    else doc=((dynamic)collection).Open(Filename:path,UpdateLinks:0,ReadOnly:false,AddToMru:false);
    if(app=="powerpoint"){object windows=null,win=null;try{windows=((dynamic)doc).Windows;win=((dynamic)windows).Item(1);((dynamic)win).Activate();}finally{Release(win);Release(windows);}}else ((dynamic)doc).Activate();
    if(app=="powerpoint")((dynamic)doc).Saved=0;else ((dynamic)doc).Saved=false;
   }finally{if(changed)application.AutomationSecurity=security;Release(doc);Release(collection);}
  }
  public object OpenArtifact(string path,string sourceState,CancellationToken token){binding().CheckSource();if(sourceState!=null&&State()!=sourceState)throw new OfficeFault("source_changed");token.ThrowIfCancellationRequested();OpenCopy(path);return new{kind="open_document",status="verified",mutated=true,saved=false,document=ActiveName()};}
  public object ImportSlides(string path,string mode,int slide,string sourceState,CancellationToken token){if(app!="powerpoint")throw new OfficeFault("powerpoint_required");path=CheckedPath(path,".pptx");binding().CheckSource();if(sourceState!=null&&State()!=sourceState)throw new OfficeFault("source_changed");token.ThrowIfCancellationRequested();dynamic doc=binding().BoundDocument;object slides=null;
   if(mode=="new")return OpenArtifact(path,sourceState,token);
   CheckpointNow("발표자료 변경 전");bool mutated=false;try{slides=doc.Slides;int old=(int)((dynamic)slides).Count;int position=mode=="regenerate"?slide:mode=="replace"?0:old;if(position<0||position>old||mode=="regenerate"&&slide>=old)throw new OfficeFault("slide_index_invalid");mutated=true;int inserted=(int)((dynamic)slides).InsertFromFile(path,position);
    if(mode=="replace")for(int i=old+inserted;i>inserted;i--){object s=((dynamic)slides).Item(i);try{((dynamic)s).Delete();}finally{Release(s);}}
    else if(mode=="regenerate"){if(inserted!=1)throw new OfficeFault("slide_count_mismatch");object s=((dynamic)slides).Item(slide+inserted+1);try{((dynamic)s).Delete();}finally{Release(s);}}
    int expected=mode=="replace"?inserted:mode=="regenerate"?old:old+inserted;bool match=inserted>0&&(int)((dynamic)slides).Count==expected;
    return new{kind="import_slides",status=match?"verified":"partial",mutated,saved=false,count=inserted,slides=ReadSlideText(),document=binding().DocumentName};
   }catch{if(mutated)return new{kind="import_slides",status="partial",mutated=true,saved=false,error="slide_import_uncertain"};throw;}finally{Release(slides);}
  }
  public object ReadSlideText(){if(app!="powerpoint")throw new OfficeFault("powerpoint_required");binding().CheckSource();dynamic doc=binding().BoundDocument;object slides=null;var values=new List<object>();try{slides=doc.Slides;for(int i=1;i<=(int)((dynamic)slides).Count;i++){object s=null,shapes=null;try{s=((dynamic)slides).Item(i);shapes=((dynamic)s).Shapes;var texts=new List<string>();for(int j=1;j<=(int)((dynamic)shapes).Count;j++){object sh=null,frame=null,range=null;try{sh=((dynamic)shapes).Item(j);if(Convert.ToInt32(((dynamic)sh).HasTextFrame)!=0){frame=((dynamic)sh).TextFrame;range=((dynamic)frame).TextRange;texts.Add((string)((dynamic)range).Text);}}finally{Release(range);Release(frame);Release(sh);}}values.Add(new{slide=i,texts});}finally{Release(shapes);Release(s);}}return values;}finally{Release(slides);}}
  public object RenderSlides(int first,int count,int width,CancellationToken token){if(app!="powerpoint")throw new OfficeFault("powerpoint_required");binding().CheckSource();if(first<1||count<1||count>20||width<320||width>2560)throw new OfficeFault("render_range_invalid");object slides=null,setup=null;var files=new List<object>();try{dynamic doc=binding().BoundDocument;slides=doc.Slides;setup=doc.PageSetup;int total=(int)((dynamic)slides).Count;if(first>total)throw new OfficeFault("slide_index_invalid");int height=(int)Math.Round(width*Convert.ToDouble(((dynamic)setup).SlideHeight)/Convert.ToDouble(((dynamic)setup).SlideWidth));for(int i=first;i<=Math.Min(total,first+count-1);i++){token.ThrowIfCancellationRequested();object s=((dynamic)slides).Item(i);var path=FreshPath(".png");try{((dynamic)s).Export(path,"PNG",width,height);CheckedPath(path,".png");files.Add(new{slide=i,path,width,height});}finally{Release(s);}}return new{status="verified",total,files};}finally{Release(setup);Release(slides);}}
  public object ImportWordContent(string path,string expectedHash,CancellationToken token){if(app!="word")throw new OfficeFault("word_required");path=CheckedPath(path,".html");binding().CheckSource();token.ThrowIfCancellationRequested();CheckpointNow("본문 가져오기 전");object range=null;try{dynamic doc=binding().BoundDocument;range=doc.Content;((dynamic)range).Text="";((dynamic)range).InsertFile(path);object actual=doc.Content;try{string text=(string)((dynamic)actual).Text;return new{kind="import_word_content",status=Hash(Encoding.UTF8.GetBytes(System.Text.RegularExpressions.Regex.Replace(text,@"[\s\u0007]+"," ").Trim()))==expectedHash?"verified":"partial",mutated=true,saved=false,document=binding().DocumentName,textLength=text.Length};}finally{Release(actual);}}catch{return new{kind="import_word_content",status="partial",mutated=true,error="content_import_uncertain"};}finally{Release(range);}}

  public void Dispose(){/* encrypted checkpoints remain for the life of this pane; never delete an open generated document */}
 }
}
